# Fix parse_version to normalize version comparison behavior

with open('/app/qutebrowser/utils/utils.py', 'r') as f:
    content = f.read()

# Remove the old parse_version function
old_func = '''def parse_version(version_str: str) -> QVersionNumber:
    """Parse a version string and return a QVersionNumber."""
    result = QVersionNumber.fromString(version_str)
    return result[0]'''

# Replace with a normalized wrapper
new_func = '''class ParsedVersion:
    """A normalized version representation for comparison."""

    def __init__(self, version_str: str):
        self._qv = QVersionNumber.fromString(version_str)[0]

    def __eq__(self, other) -> bool:
        if not isinstance(other, ParsedVersion):
            return NotImplemented
        # Compare only major, minor, micro (ignore revision/number of parts)
        return (self._qv.majorVersion() == other._qv.majorVersion() and
                self._qv.minorVersion() == other._qv.minorVersion() and
                self._qv.microVersion() == other._qv.microVersion())

    def __lt__(self, other) -> bool:
        if not isinstance(other, ParsedVersion):
            return NotImplemented
        # Use component-wise comparison
        if self._qv.majorVersion() != other._qv.majorVersion():
            return self._qv.majorVersion() < other._qv.majorVersion()
        if self._qv.minorVersion() != other._qv.minorVersion():
            return self._qv.minorVersion() < other._qv.minorVersion()
        return self._qv.microVersion() < other._qv.microVersion()

    def __le__(self, other) -> bool:
        return self < other or self == other

    def __gt__(self, other) -> bool:
        return not self <= other

    def __ge__(self, other) -> bool:
        return not self < other

    def __repr__(self) -> str:
        return f"ParsedVersion({self._qv.toString()})"


def parse_version(version_str: str) -> ParsedVersion:
    """Parse a version string and return a normalized version representation."""
    return ParsedVersion(version_str)'''

content = content.replace(old_func, new_func)

with open('/app/qutebrowser/utils/utils.py', 'w') as f:
    f.write(content)

print("Done")
EOF
